#!/usr/bin/env python3
from pathlib import Path
import shutil, sys
if len(sys.argv)!=3: raise SystemExit('usage: transform base candidate')
base=Path(sys.argv[1]); root=Path(sys.argv[2])
if root.exists(): shutil.rmtree(root)
shutil.copytree(base, root)

vgn=root/'app/src/main/java/com/hinnka/mycamera/processor/GlesIris26529SpatialRgbChromaPostprocessor.kt'
s=vgn.read_text()
old='''            float microCompactAreaEvidence = microAreaEvidence * microTwoAxisEvidence;\n            /* IRIS_26580_FAIL_CLOSED_MULTICOLOR_OBJECT_VETO'''
new='''            float microCompactAreaEvidence = microAreaEvidence * microTwoAxisEvidence;\n\n            /* IRIS_26581_OCCLUSION_GAP_BACKGROUND_OWNER\n             * A tiny bright background opening between two darker foreground edges must not be\n             * classified by the local foreground majority. Require an opposing dark near-pair plus\n             * a matching bright/color-consistent far pair before assigning background ownership.\n             * This is deliberately strict: a tiny LED/flower/logo cannot satisfy the far-background\n             * continuation proof merely because it is small or saturated. */\n            const ivec2 gapAxes[4] = ivec2[4](\n                ivec2(1,0), ivec2(0,1), ivec2(1,1), ivec2(1,-1));\n            float gapBackgroundWeight = 0.0;\n            vec3 gapBackgroundChromaSum = vec3(0.0);\n            float gapPairEvidence = 0.0;\n            for (int g = 0; g < 4; ++g) {\n                ivec2 d = gapAxes[g];\n                vec3 nearA = loadRgb(p + d);\n                vec3 nearB = loadRgb(p - d);\n                vec3 farA = loadRgb(p + 2 * d);\n                vec3 farB = loadRgb(p - 2 * d);\n                float nearAY = luminanceOf(nearA);\n                float nearBY = luminanceOf(nearB);\n                float farAY = luminanceOf(farA);\n                float farBY = luminanceOf(farB);\n                float nearDarkA = smoothstep(0.18, 0.48,\n                    (centerLuma - nearAY) / max(max(centerLuma, nearAY), 0.060));\n                float nearDarkB = smoothstep(0.18, 0.48,\n                    (centerLuma - nearBY) / max(max(centerLuma, nearBY), 0.060));\n                float farSameA = 1.0 - smoothstep(0.09, 0.27,\n                    abs(farAY - centerLuma) / max(max(farAY, centerLuma), 0.060));\n                float farSameB = 1.0 - smoothstep(0.09, 0.27,\n                    abs(farBY - centerLuma) / max(max(farBY, centerLuma), 0.060));\n                vec3 farNormA = (farA - vec3(farAY)) / max(farAY, 0.060);\n                vec3 farNormB = (farB - vec3(farBY)) / max(farBY, 0.060);\n                float farMagA = length(farNormA);\n                float farMagB = length(farNormB);\n                float farNeutralPair = (1.0 - smoothstep(0.035, 0.090, farMagA)) *\n                    (1.0 - smoothstep(0.035, 0.090, farMagB));\n                float farHuePair = smoothstep(0.72, 0.92, hueAgreement(farNormA, farNormB));\n                float farColorAgreement = max(farNeutralPair, farHuePair);\n                float pairEvidence = nearDarkA * nearDarkB * farSameA * farSameB *\n                    farColorAgreement;\n                gapPairEvidence = max(gapPairEvidence, pairEvidence);\n                gapBackgroundWeight += pairEvidence;\n                gapBackgroundChromaSum += 0.5 * (farNormA + farNormB) * pairEvidence;\n            }\n            /* IRIS_26580_FAIL_CLOSED_MULTICOLOR_OBJECT_VETO'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
old='''            vec3 correctedChroma = centerChroma + desiredDelta * boundedScale * correction;\n            if (length(correctedChroma) > centerMagnitude && length(correctedChroma) > 1.0e-7) {\n                correctedChroma *= centerMagnitude / length(correctedChroma);\n            }\n\n            vec3 correctedRgb = clamp(vec3(centerLuma) + correctedChroma, 0.0, 1.0);'''
new='''            vec3 correctedChroma = centerChroma + desiredDelta * boundedScale * correction;\n            if (length(correctedChroma) > centerMagnitude && length(correctedChroma) > 1.0e-7) {\n                correctedChroma *= centerMagnitude / length(correctedChroma);\n            }\n\n            /* IRIS_26581_GAP_BACKGROUND_CHROMA_RESTORE\n             * When the strict paired-edge proof succeeds, the far samples are the actual supported\n             * background owner. Restore only toward their observed chroma; never invent a hue or use\n             * surrounding foreground color. This repair is independent of the false-color gate so a\n             * real blue sky opening can be made uniform even though blue itself is real color. */\n            if (gapBackgroundWeight > 1.0e-6) {\n                vec3 gapNormalizedChroma = gapBackgroundChromaSum / gapBackgroundWeight;\n                vec3 gapTargetChroma = gapNormalizedChroma * centerScale;\n                float gapDisagreement = smoothstep(0.045, 0.150,\n                    length(centerNormalizedChroma - gapNormalizedChroma));\n                float gapOwnership = smoothstep(0.42, 0.88, gapPairEvidence) * gapDisagreement;\n                correctedChroma = mix(correctedChroma, gapTargetChroma, 0.88 * gapOwnership);\n            }\n\n            vec3 correctedRgb = clamp(vec3(centerLuma) + correctedChroma, 0.0, 1.0);'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
vgn.write_text(s)

sabre=root/'app/src/main/java/com/hinnka/mycamera/processor/GlesMgcRawSabreShaders.kt'
s=sabre.read_text()
old='''        vec3 irisTopologyGuide(ivec2 globalP, vec3 bilinearGuide, float directY, float confidence) {'''
new='''        vec3 irisTopologyGuide(ivec2 globalP, vec3 bilinearGuide, float directY, float confidence,\n                              out float materialBoundary) {'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
old='''            float edgeGate = irisSmooth01((maxYDelta - 0.018) / 0.095);\n            float crossEdgeEvidence = irisSmooth01((crossSideSpatial - 0.06) / 0.30);\n            float topologyGate = edgeGate * mix(0.70, 1.0, crossEdgeEvidence);\n            vec3 selectedChroma = mix(bilinearChroma, topologyChroma, topologyGate);'''
new='''            float edgeGate = irisSmooth01((maxYDelta - 0.018) / 0.095);\n            float crossEdgeEvidence = irisSmooth01((crossSideSpatial - 0.06) / 0.30);\n            /* IRIS_26581_DECISIVE_CROSS_EDGE_CHROMA_VETO\n             * At an unambiguous material boundary, do not retain a bilinear cross-edge chroma\n             * bridge. Ambiguous/low-contrast regions keep the proven 26580 soft transition. */\n            float decisiveBoundary = irisSmooth01((maxYDelta - 0.050) / 0.075) *\n                irisSmooth01((crossSideSpatial - 0.10) / 0.24);\n            float topologyGate = max(edgeGate * mix(0.70, 1.0, crossEdgeEvidence),\n                decisiveBoundary);\n            materialBoundary = max(decisiveBoundary, edgeGate * crossEdgeEvidence);\n            vec3 selectedChroma = mix(bilinearChroma, topologyChroma, topologyGate);'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
old='''            float denom = max(lowY, 0.015);\n            float d00 = (y00 - lowY) / denom;\n            float d10 = (y10 - lowY) / denom;\n            float d01 = (y01 - lowY) / denom;\n            float d11 = (y11 - lowY) / denom;\n            float maxAbsDetail = max(max(abs(d00), abs(d10)), max(abs(d01), abs(d11)));\n            float shapeScale = maxAbsDetail > 1.0e-6 ? min(1.0, 0.42 / maxAbsDetail) : 0.0;\n            float directDetail = ((directY - lowY) / denom) * shapeScale;\n            float targetY = max(guideY + guideBlockY * directDetail * confidence, 0.0);\n            float factor = guideY > 1.0e-5 ? clamp(targetY / guideY, 0.68, 1.47) : 1.0;\n            vec3 guideRgb = irisTopologyGuide(globalP, bilinearGuideRgb, directY, confidence);'''
new='''            /* IRIS_26581_MATERIAL_SEPARATED_SR_DETAIL_ENVELOPE\n             * Zero-DC over a mixed leaf/sky 2x2 block can create a compensating dark/bright pair\n             * across the material edge. Preserve the exact old zero-DC residual in uniform cells,\n             * but at a proven boundary center the direct-CFA residual only on the current material\n             * side. A side represented by only one trustworthy subpixel does not fabricate detail. */\n            float materialBoundary = 0.0;\n            vec3 guideRgb = irisTopologyGuide(globalP, bilinearGuideRgb, directY, confidence,\n                materialBoundary);\n            float denom = max(lowY, 0.015);\n            float d00 = (y00 - lowY) / denom;\n            float d10 = (y10 - lowY) / denom;\n            float d01 = (y01 - lowY) / denom;\n            float d11 = (y11 - lowY) / denom;\n            float maxAbsDetail = max(max(abs(d00), abs(d10)), max(abs(d01), abs(d11)));\n            float shapeScale = maxAbsDetail > 1.0e-6 ? min(1.0, 0.42 / maxAbsDetail) : 0.0;\n            float blockDetail = ((directY - lowY) / denom) * shapeScale;\n\n            float rel00 = abs(y00 - directY) / max(max(y00, directY), 0.030);\n            float rel10 = abs(y10 - directY) / max(max(y10, directY), 0.030);\n            float rel01 = abs(y01 - directY) / max(max(y01, directY), 0.030);\n            float rel11 = abs(y11 - directY) / max(max(y11, directY), 0.030);\n            float mw00 = 1.0 - irisSmooth01((rel00 - 0.10) / 0.34);\n            float mw10 = 1.0 - irisSmooth01((rel10 - 0.10) / 0.34);\n            float mw01 = 1.0 - irisSmooth01((rel01 - 0.10) / 0.34);\n            float mw11 = 1.0 - irisSmooth01((rel11 - 0.10) / 0.34);\n            float materialWeight = mw00 + mw10 + mw01 + mw11;\n            float materialMean = (y00 * mw00 + y10 * mw10 + y01 * mw01 + y11 * mw11) /\n                max(materialWeight, 1.0e-6);\n            float materialDenom = max(materialMean, 0.015);\n            float md00 = (y00 - materialMean) / materialDenom;\n            float md10 = (y10 - materialMean) / materialDenom;\n            float md01 = (y01 - materialMean) / materialDenom;\n            float md11 = (y11 - materialMean) / materialDenom;\n            float materialMaxAbs = max(max(abs(md00) * step(0.20, mw00),\n                                           abs(md10) * step(0.20, mw10)),\n                                       max(abs(md01) * step(0.20, mw01),\n                                           abs(md11) * step(0.20, mw11)));\n            float materialShapeScale = materialMaxAbs > 1.0e-6 ?\n                min(1.0, 0.42 / materialMaxAbs) : 0.0;\n            float materialDetail = ((directY - materialMean) / materialDenom) *\n                materialShapeScale;\n            float materialSupportGate = irisSmooth01((materialWeight - 1.15) / 1.10);\n            float directDetail = mix(blockDetail, materialDetail, materialBoundary);\n            float detailConfidence = confidence * mix(1.0, materialSupportGate, materialBoundary);\n            float detailScaleY = mix(guideBlockY, guideY, materialBoundary);\n            float targetY = max(guideY + detailScaleY * directDetail * detailConfidence, 0.0);\n            float factor = guideY > 1.0e-5 ? clamp(targetY / guideY, 0.68, 1.47) : 1.0;\n\n            /* Boundary-only luminance envelope: the amount of permitted SR excursion is derived\n             * from variation already observed on the selected material side. Uniform sky therefore\n             * cannot acquire a bright halo simply to compensate a dark leaf residual, while textured\n             * foliage keeps substantially more true subpixel modulation. */\n            float materialMinY = directY;\n            float materialMaxY = directY;\n            if (mw00 > 0.35) { materialMinY = min(materialMinY, y00); materialMaxY = max(materialMaxY, y00); }\n            if (mw10 > 0.35) { materialMinY = min(materialMinY, y10); materialMaxY = max(materialMaxY, y10); }\n            if (mw01 > 0.35) { materialMinY = min(materialMinY, y01); materialMaxY = max(materialMaxY, y01); }\n            if (mw11 > 0.35) { materialMinY = min(materialMinY, y11); materialMaxY = max(materialMaxY, y11); }\n            float materialRelativeRange = (materialMaxY - materialMinY) / max(materialMean, 0.015);\n            float edgeExcursion = clamp(0.045 + 0.70 * materialRelativeRange, 0.060, 0.30);\n            float envelopeFactor = clamp(factor, 1.0 - edgeExcursion, 1.0 + edgeExcursion);\n            factor = mix(factor, envelopeFactor, materialBoundary);'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
sabre.write_text(s)

vp=root/'app/version.properties'
v=vp.read_text()
assert v.count('VERSION_NAME=0.9726580')==1
assert v.count('VERSION_BUILD=26580')==1
v=v.replace('VERSION_NAME=0.9726580','VERSION_NAME=0.9726581').replace('VERSION_BUILD=26580','VERSION_BUILD=26581')
vp.write_text(v)
print('PASS transformed 26580 -> 26581 gap-owner / edge-envelope candidate')
